INSERT INTO `giveaway_templates` (`id`, `prize_name`, `description`, `prize_type`, `prize_value`, `image`, `max_entries_per_user`, `required_entries`, `animation_style`, `is_active`, `times_used`, `last_used_at`, `created_at`, `updated_at`) VALUES
(1, 'Trailer Load of Firewood', 'We’re giving away a FREE 6x4 trailer load of quality firewood, delivered straight to one lucky winner.\r\n\r\nThis giveaway is part of our JJ’s Firewood App weekly draws, where every eligible order placed through the app earns a permanent entry into not just this draw, but every future weekly giveaway as well.\r\n\r\nThat means once you’re in, you stay in.\r\n\r\n✅ Free 6x4 trailer load of firewood\r\n✅ Delivered to the winner\r\n✅ App-exclusive giveaway\r\n✅ Permanent entries carry over into every weekly draw\r\n✅ More giveaways coming every week\r\n\r\nTo enter, simply place your order through the JJ’s Firewood app and you’ll automatically go into the draw.\r\n\r\nThanks again to everyone supporting the app and getting involved — we’re excited to keep giving back every week. 🔥', 'bundle', 280.00, 'giveaway_images/1792056029_6ad09add9571a.jpg', NULL, NULL, 'lottery_balls', 1, 2, '2026-10-16 12:00:06', '2026-10-15 17:13:34', '2026-10-16 12:00:06'),
(2, '10x Firewood Bags', 'We’re giving away 10x firewood bags consisting of quality firewood, delivered straight to one lucky winner.\r\n\r\nThis giveaway is part of our JJ’s Firewood App weekly draws, where every eligible order placed through the app earns a permanent entry into not just this draw, but every future weekly giveaway as well.\r\n\r\nThat means once you’re in, you stay in.\r\n\r\n✅ Free 10x bags of firewood \r\n✅ Delivered to the winner\r\n✅ App-exclusive giveaway\r\n✅ Permanent entries carry over into every weekly draw\r\n✅ More giveaways coming every week\r\n\r\nTo enter, simply place your order through the JJ’s Firewood app and you’ll automatically go into the draw.\r\n\r\nThanks again to everyone supporting the app and getting involved — we’re excited to keep giving back every week. 🔥', 'bundle', 250.00, 'giveaway_images/1792056060_6ad09afc8400f.png', NULL, NULL, 'lottery_balls', 1, 1, '2026-10-30 12:00:08', '2026-10-15 17:13:39', '2026-10-30 12:00:08'),
(3, '$100 OFF your next order.', '🔥 **WIN $100 OFF YOUR NEXT FIREWOOD ORDER!** 🔥\r\n\r\nWe\'re giving one lucky winner **$100 OFF** their next order with JJ\'s Firewood Supplies!\r\n\r\nWhether you\'re stocking up for winter or getting organised early, this is your chance to save big on quality firewood delivered straight to your door.\r\n\r\n🏆 **Prize:** $100 off your next firewood order\r\n\r\nGood luck from the team at JJ\'s Firewood Supplies! 🔥\r\n\r\n*Prize is redeemable against a future order. Not exchangeable for cash. Subject to giveaway terms and conditions.*', 'discount', 100.00, 'giveaway_images/1792055881_6ad09a49716d7.png', NULL, NULL, 'lottery_balls', 1, 2, '2026-10-23 12:00:09', '2026-10-15 17:13:42', '2026-10-23 12:00:09'),
(4, 'WIN A $50 VOUCHER', 'WIN $50 OFF YOUR NEXT FIREWOOD ORDER!\r\n\r\nWe’re giving away one lucky winner $50 WORTH OF IN APP CREDIT to use on their next JJ’s Firewood Supplies order!\r\n\r\nScore a $50 voucher to put towards your next order and save on keeping your home warm, enjoying a cosy night by the fire or simply stocking up for later.\r\n\r\nNO EXPIRY. Use voucher whenever suits you!\r\n\r\nMore warmth, less spending - that’s a win!\r\n\r\n*All vouchers are to be redeemed via the JJ’s Firewood Supplies app only for firewood purchases. Not redeemable via any other ordering system (via web, phone or social media bookings) and is not exchangeable for cash. Limit of 1x voucher per transaction. All winners must have a delivery point in our catchment in the Perth metro area unless advised otherwise. See our full terms and conditions for more details.', 'discount', 50.00, 'giveaway_images/1792300871_6ad4574792479.png', NULL, NULL, 'lottery_balls', 0, 0, NULL, '2026-10-18 05:21:11', '2026-10-18 05:21:19'),
(5, 'WIN A $100 VOUCHER', 'WIN $100 OFF YOUR NEXT FIREWOOD ORDER!\r\n\r\nWe’re giving away one lucky winner $100 WORTH OF IN APP CREDIT to use on their next JJ’s Firewood Supplies order!\r\n\r\nScore a $100 voucher to put towards your next order and save on keeping your home warm, enjoying a cosy night by the fire or simply stocking up for later.\r\n\r\nNO EXPIRY. Use voucher whenever suits you!\r\n\r\nMore warmth, less spending - that’s a win!\r\n\r\n*All vouchers are to be redeemed via the JJ’s Firewood Supplies app only for firewood purchases. Not redeemable via any other ordering system (via web, phone or social media bookings) and is not exchangeable for cash. Limit of 1x voucher per transaction. All winners must have a delivery point in our catchment in the Perth metro area unless advised otherwise. See our full terms and conditions for more details.', 'discount', 100.00, 'giveaway_images/1792301122_6ad4584298a68.png', NULL, NULL, 'lottery_balls', 0, 0, NULL, '2026-10-18 05:25:22', '2026-10-18 05:25:22'),
(6, 'WIN A $200 VOUCHER', 'WIN $200 OFF YOUR NEXT FIREWOOD ORDER!\r\n\r\nWe’re giving away one lucky winner $200 WORTH OF IN APP CREDIT to use on their next JJ’s Firewood Supplies order!\r\n\r\nScore a $200 voucher to put towards your next order and save on keeping your home warm, enjoying a cosy night by the fire or simply stocking up for later.\r\n\r\nNO EXPIRY. Use voucher whenever suits you!\r\n\r\nMore warmth, less spending - that’s a win!\r\n\r\n*All vouchers are to be redeemed via the JJ’s Firewood Supplies app only for firewood purchases. Not redeemable via any other ordering system (via web, phone or social media bookings) and is not exchangeable for cash. Limit of 1x voucher per transaction. All winners must have a delivery point in our catchment in the Perth metro area unless advised otherwise. See our full terms and conditions for more details.', 'discount', 200.00, 'giveaway_images/1792301275_6ad458db09d0b.png', NULL, NULL, 'lottery_balls', 0, 0, NULL, '2026-10-18 05:26:21', '2026-10-18 05:27:55'),
(7, 'WIN 1T OF FIREWOOD', 'WIN A FREE LOAD OF FIREWOOD DELIVERED STRAIGHT TO YOUR DOOR!\r\n\r\nImagine scoring a whole load of firewood for FREE.. Now that’s a prize worth winning!\r\n\r\nWe’re giving away one lucky winner 1T OF FIREWOOD. No purchases required to recieve this win, we will deliver for FREE to you!\r\n\r\nMore fires, more warmth and a whole lot of savings - all with out spending a cent on wood!\r\n\r\nWeight is approximate as we measure by scoops.\r\n\r\nApprox. 1T = 4x scoops or an 8x5 trailer load \r\n\r\n*Wood type delivered will be bush mix or whatever is seasonably available at the time. Images shown are for advertising purposes only and does not reflect the win load. Not redeemable via any other ordering system (via web, phone or social media bookings) and is not exchangable for cash. All winners must have a delivery point in our catchment in the Perth metro area unless advised otherwise. See our full terms and conditions for more details.', 'bundle', 399.00, 'giveaway_images/1792301435_6ad4597b29bfa.png', NULL, NULL, 'lottery_balls', 0, 0, NULL, '2026-10-18 05:30:35', '2026-10-18 05:30:35'),
(8, 'WIN A WARMER STARTER PACK', 'WIN A FREE WARMER STARTER PACK WORTH ALMOST $100!\r\n\r\nEverything you need to get the fire going and keep those cosy vibes alive!\r\n\r\nOur warmer pack includes:\r\n\r\n- 3x bags of firewood\r\n- 1x bag of kindling\r\n- 2x Jiffy firelighters\r\n\r\nSimply purchase any load of firewood through the app to recieve your free warmer starter pack added on to your order for free. Make your fires roar with JJ’s!\r\n\r\nLess hassle, more warmth and everything you need to enjoy a roaring fire - all for free!\r\n\r\n*Winner must purchase an order to receive starter pack. Not redeemable via any other ordering system (via web, phone or social media bookings) and is not exchangeable for cash. All winners must have a delivery point in our catchment in the Perth metro area unless advised otherwise. See our full terms and conditions for more details.', 'bundle', 85.40, 'giveaway_images/1792301537_6ad459e1c4703.png', NULL, NULL, 'lottery_balls', 0, 0, NULL, '2026-10-18 05:32:17', '2026-10-18 05:32:17'),
(9, 'WIN THE ULTIMATE FIRE PIT PACK', 'WIN THE ULTIMATE FIRE PIT PACK VALUED AT ALMOST $350!\r\n\r\nGet ready to turn your next outdoor gathering into the ultimate fireside experience. This prize is perfect for making those magical memories even better!\r\n\r\nOur ultimate fire pit pack includes:\r\n\r\n- HT firewood\r\n- 1x bag of firewood\r\n- 1x bag of kindling\r\n- 2x Jiffy firelighters\r\n\r\nSimply purchase any load of firewood through the app to recieve your free warmer starter pack added on to your order for free. Make your fires roar with JJ’s!\r\n\r\nMore warmth, more memories and more nights spent around the fire - all for free!\r\n\r\nWeight is approximate as we measure by scoops.\r\n\r\nApprox. HT = 2x scoops or a 6x4 trailer load\r\n\r\n* Wood type delivered will be bush mix or whatever is seasonably available at the time. Images shown are for advertising purposes only and does not reflect the win load. Not redeemable via any other ordering system (via web, phone or social media bookings) and is not exchangeable for cash. All winners must have a delivery point in our catchment in the Perth metro area unless advised otherwise. See our full terms and conditions for more details.', 'bundle', 325.40, 'giveaway_images/1792301637_6ad45a4512156.png', NULL, NULL, 'lottery_balls', 0, 0, NULL, '2026-10-18 05:33:57', '2026-10-18 05:33:57'),
(10, 'FREE FIREWOOD FOR A MONTH', 'WIN A MONTHS WORTH OF FIREWOOD FOR YOUR HOME!\r\n\r\nKeep the cold outside and the warmth in! Imagine a whole month of warm, toasty nights without spending a single cent on wood.\r\n\r\nWe’re giving you the chance to win a month’s supply of our high quality wood. Our HT load is gauranteed to keep your home warm right when you need it most.\r\n\r\nMore crackling dry wood, less dollars spent and one less thing to worry about - for FREE!\r\n\r\nWeight is approximate as we measure by scoops.\r\n\r\nApprox. HT = 2x scoops or a 6x4 trailer load\r\n\r\n* Wood type delivered will be bush mix or whatever is seasonably available at the time. Images shown are for advertising purposes only and does not reflect the win load. Not redeemable via any other ordering system (via web, phone or social media bookings) and is not exchangeable for cash. All winners must have a delivery point in our catchment in the Perth metro area unless advised otherwise. See our full terms and conditions for more details.', 'bundle', 280.00, 'giveaway_images/1792301741_6ad45aad09f0c.png', NULL, NULL, 'lottery_balls', 0, 0, NULL, '2026-10-18 05:35:41', '2026-10-18 05:35:50'),
(11, 'WIN 10X FIREWOOD BAGS', 'RECIEVE 10X FIREWOOD BAGS FOR FREE! NO PURCHASE REQUIRED.\r\n\r\nYour next outdoor adventure just got a whole lot better!\r\n\r\nPicture nights under the stars, good company and a crackling fire.. with ample supply of our convenient firewood bags to keep you going.\r\n\r\nGreat for camping trips, backyard fire pits and making memories around the flames.\r\n\r\nMore flames, more fun and zero cost - now that’s a hot prize!\r\n\r\n*Not redeemable via any other ordering system (via web, phone or social media bookings) and is not exchangeable for cash. All winners must have a delivery point in our catchment in the Perth metro area unless advised otherwise. See our full terms and conditions for more details.', 'bundle', 250.00, 'giveaway_images/1792301839_6ad45b0fae75a.png', NULL, NULL, 'lottery_balls', 0, 0, NULL, '2026-10-18 05:37:19', '2026-10-18 05:37:19'),
(12, 'WIN A FIRE STARTER KIT', 'DESCRIPTION:\r\n\r\nRECIEVE A FIRE STARTER KIT WITH YOUR NEXT PURCHASE!\r\n\r\nGetting your fires going has never been easier! With our fire starter pack, you’ll have everything you need to get those flames started in no time.\r\n\r\nFire starter pack contains:\r\n\r\n- 5x firelighters\r\n- 2x kindling bags\r\n\r\nLess fuss, less hassle and more time enjoying the warmth of a roaring fire!\r\n\r\n*Fire starter kit is an add on to an order. An order must be placed to receive this prize. Not redeemable via any other ordering system (via web, phone or social media bookings) and is not exchangeable for cash. All winners must have a delivery point in our catchment in the Perth metro area unless advised otherwise. See our full terms and conditions for more details.', 'bundle', 57.50, 'giveaway_images/1792301937_6ad45b716eb59.png', NULL, NULL, 'lottery_balls', 0, 0, NULL, '2026-10-18 05:38:57', '2026-10-18 05:38:57');
